  brush.beginShape(0.5);
  brush.vertex(0, 200); brush.vertex(150, 185); brush.vertex(260, 190); brush.vertex(400, 205); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
  brush.fill("#7d8a7b", 240);
  brush.beginShape(0.5);
  brush.vertex(0, 320); brush.vertex(100, 240); brush.vertex(250, 250); brush.vertex(400, 310); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
  brush.fill("#5e6b5a", 230);
  brush.beginShape(0.4);
  brush.vertex(0, 330); brush.vertex(150, 255); brush.vertex(260, 265); brush.vertex(400, 335); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
  brush.fill("#f2b5a0", 240);
  brush.beginShape(0.6);
  brush.vertex(0, 220); brush.vertex(180, 200); brush.vertex(330, 225); brush.vertex(400, 210); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
  for (let b of brush.brushes) {
    for (let i = 0; i < b.length(); i++) {
      let a = b[i];
      let b = b[(i + 1) % b.length()];
      if (a[1] < 0 && a[1] > b[1]) continue;
      if (a[0] < 0 && a[0] > b[0]) continue;
      if ((a[0] * a[1] + b[0] * b[1]) <= (a[2] * a[1] + b[2] * b[1])) {
        brush.fill(a[3], 240);
        brush.circle(a[0], a[1], 7 + (i * 4));
      }
    }
  }
}

